mapper.sql:
WITH reset_points AS ( SELECT student_id, created_at AS reset_at FROM contact_log UNION ALL SELECT student_id, selected_at AS reset_at FROM student_intent_history WHERE status IN ('EMPLOYED', 'RESTING') ), last_reset AS ( SELECT student_id, MAX(reset_at) AS reset_at FROM reset_points GROUP BY student_id ), ordered_responses AS ( SELECT r.student_id, ri.response, ri.responded_at, SUM(CASE WHEN ri.response = 'PASS' AND COALESCE(ri.pass_reason, '') NOT IN ('ALREADY_EMPLOYED', 'TAKING_BREAK') THEN 0 ELSE 1 END) OVER ( PARTITION BY r.student_id ORDER BY ri.responded_at DESC, ri.id DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS non_pass_count FROM recommendation_item ri JOIN recommendation r ON r.id = ri.recommendation_id LEFT JOIN last_reset lr ON lr.student_id = r.student_id WHERE ri.response IN ('PASS', 'APPLY', 'HELP') AND ri.responded_at IS NOT NULL AND (lr.reset_at IS NULL OR ri.responded_at > lr.reset_at)
AND r.student_id IN #{studentId}
) SELECT student_id, COUNT(*) AS consecutive_pass_count, MAX(responded_at) AS last_pass_at FROM ordered_responses WHERE non_pass_count = 0 GROUP BY student_id
